export const ENTER_KEY="Enter";export const ESCAPE_KEY="Escape";export const TAB_KEY="Tab";export const ARROW_KEYS=new Set(["ArrowUp","ArrowDown","ArrowLeft","ArrowRight"]);export function keyIsArrowKey(r){return ARROW_KEYS.has(r)}export function isEscKey(r){return"Escape"===r.key}export function isEnterOrSpaceKey(r){return"Enter"===r.key||" "===r.key}